export function f(values, Date) {
  let sum = 0;
  process: for (let i = 0; i < values.length; i++) { if (i < 0) break process; }
  for (const value of values) sum += value;
  const index = 0;
  return Math.round(Math.sqrt(sum + values[index])) + Date;
}

